global.schema:
type PriceBookState {
  baseCurrency: String!
  latest: [LatestPrice!]!
  history: [PricePoint!]!
  status: FetchStatus!
}

type LatestPrice {
  asset: String!
  price: String!
  source: String!
  fetchedAt: DateTime!
}

type PricePoint {
  asset: String!
  hour: DateTime!
  price: String!
  source: String!
}

type FetchStatus {
  lastFetchAt: DateTime
  lastError: String
}

operations.schema:
input RecordPricesInput {
  baseCurrency: String!
  prices: [RecordedPriceInput!]!
  hour: DateTime!
  fetchedAt: DateTime!
}

input RecordedPriceInput {
  asset: String!
  price: String!
  source: String!
}

operations.reducer:
if (action.input.prices.length === 0) {
  throw new EmptyRecordError("A price record must carry at least one price");
}
const isDecimal = (value: string) => /^(0|[1-9][0-9]*)(\.[0-9]+)?$/.test(value);
for (const price of action.input.prices) {
  if (!isDecimal(price.price)) {
    throw new InvalidAmountError(`${price.price} is not a decimal amount`);
  }
}
for (const price of action.input.prices) {
  const latest = state.latest.find((p) => p.asset === price.asset);
  if (latest) {
    latest.price = price.price;
    latest.source = price.source;
    latest.fetchedAt = action.input.fetchedAt;
  } else {
    state.latest.push({
      asset: price.asset,
      price: price.price,
      source: price.source,
      fetchedAt: action.input.fetchedAt,
    });
  }
  const point = state.history.find(
    (h) => h.asset === price.asset && h.hour === action.input.hour,
  );
  if (point) {
    point.price = price.price;
    point.source = price.source;
  } else {
    state.history.push({
      asset: price.asset,
      hour: action.input.hour,
      price: price.price,
      source: price.source,
    });
  }
}
state.baseCurrency = action.input.baseCurrency;
state.status.lastFetchAt = action.input.fetchedAt;
state.status.lastError = null;

if (!/^[A-Z]{3}$/.test(action.input.baseCurrency)) {
  throw new InvalidCurrencyError(
    `${action.input.baseCurrency} is not a 3-letter currency code`,
  );
}
if (action.input.baseCurrency !== state.baseCurrency) {
  // Prices stored in another currency carry no meaning here.
  state.latest = [];
  state.history = [];
}
state.baseCurrency = action.input.baseCurrency;

operations.schema:
input RecordFetchErrorInput {
  at: DateTime!
  error: String!
}
